    KnowledgeDoc("KB-001", "SSO 403 After Deployment Runbook", "identity-runbook.md", "For 403 errors after deployment, compare changed auth policies, tenant role mappings, and SSO claims. Check whether only one region is affected. Roll back the auth policy if a broad enterprise tenant is blocked. Escalate P1 issues to Identity Platform with deployment id, tenant id, region, error code, affected users, and first-seen timestamp.", ["sso", "403", "deployment", "identity"]),
    KnowledgeDoc("KB-002", "Incident Severity Matrix", "severity-policy.md", "P1 means production outage, security incident, or more than 50 enterprise users blocked. P2 means degraded production function, executive reporting risk, or time-sensitive business process. P3 means limited impact or workaround available. P4 means informational request. P1 first response target is 30 minutes, P2 is 2 hours, P3 is 1 business day, P4 is 2 business days.", ["sla", "severity", "incident"]),
    KnowledgeDoc("KB-003", "Deployment Rollback Checklist", "rollback-checklist.md", "Before rollback, identify deployment id, changed services, blast radius, customer impact, and data migration risk. Notify incident channel, freeze new releases, capture logs, run health checks, and confirm rollback owner. After rollback, verify golden signals and send customer update.", ["deployment", "rollback", "incident"]),
    KnowledgeDoc("KB-004", "Customer Communication Templates", "customer-comms.md", "Customer updates should acknowledge impact, state investigation status, avoid unsupported root-cause claims, provide next update time, and include ticket id. For P1 incidents, update every 30 minutes until mitigation. For billing disputes, confirm investigation and avoid promising refunds before finance validation.", ["customer", "reply", "communication"]),
    KnowledgeDoc("KB-005", "Cloud Alert Escalation Process", "cloud-escalation.md", "Escalate Azure App Service CPU, AKS crash loops, storage quota, backup failures, and Redis memory pressure to Cloud Operations. Include resource name, subscription, region, metric values, alert time, deployment correlation, and customer impact. P1 cloud incidents require incident commander assignment.", ["azure", "cloud", "escalation"]),
    KnowledgeDoc("KB-006", "Billing Investigation SOP", "billing-sop.md", "For duplicate charge claims, verify invoice id, payment processor event id, customer billing plan, renewal date, and refund policy. Route suspected duplicate transactions to Finance Ops and provide a customer acknowledgement with expected review time.", ["billing", "finance", "customer"]),
